	defer cancel()

	// Standard Delete Logic
	opts := []vesapi.CallOpt{
		vesapi.WithFailIfReferred(),
	}

	err = r.client.DeleteObject(ctx, ves_io_schema_views_udp_loadbalancer.ObjectType, data.Namespace.ValueString(), data.Name.ValueString(), opts...)

